import XCTest
@testable import AegisKit

/// Byte-for-byte agreement with the server's VOPRF library. The vectors were
/// generated by @cloudflare/voprf-ts (scripts/gen-voprf-vectors.mjs) with
/// fixed blinds, so the blinded element and the final output must match
/// exactly — any divergence means tickets minted on iOS wouldn't verify.
final class VOPRFVectorTests: XCTestCase {
    struct Vectors: Decodable {
        struct Case: Decodable { let input, blind, evaluationRequest, evaluation, output: String }
        let publicKey: String
        let cases: [Case]
    }

    func vectors() throws -> Vectors {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "voprf-vectors", withExtension: "json"))
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testBlindedElementsAndOutputsMatchTheServerLibrary() throws {
        let v = try vectors()
        let client = try VOPRFClient(publicKey: Data(hex: v.publicKey))
        XCTAssertEqual(v.cases.count, 4)
        for c in v.cases {
            let (request, state) = try client.blind(input: Array(Data(hex: c.input)), blind: Scalar.decode(Array(Data(hex: c.blind))))
            XCTAssertEqual(request.hex, c.evaluationRequest)
            let output = try client.finalize(state: state, evaluation: Data(hex: c.evaluation))
            XCTAssertEqual(output.hex, c.output)
        }
    }

    func testATamperedProofOrEvaluationIsRefused() throws {
        let v = try vectors()
        let client = try VOPRFClient(publicKey: Data(hex: v.publicKey))
        let c = v.cases[1]
        let (_, state) = try client.blind(input: Array(Data(hex: c.input)), blind: Scalar.decode(Array(Data(hex: c.blind))))
        var evaluation = Array(Data(hex: c.evaluation))
        evaluation[98] ^= 0x01 // last byte of s — may make s non-canonical or just wrong
        XCTAssertThrowsError(try client.finalize(state: state, evaluation: Data(evaluation)))
        // A proof from a DIFFERENT key (a server tagging users with per-user keys) fails verification.
        let otherKey = try Element.base(times: Scalar.random())
        let otherKeyClient = try VOPRFClient(publicKey: Data(otherKey.bytes))
        let (_, s2) = try otherKeyClient.blind(input: Array(Data(hex: c.input)), blind: Scalar.decode(Array(Data(hex: c.blind))))
        XCTAssertThrowsError(try otherKeyClient.finalize(state: s2, evaluation: Data(hex: c.evaluation))) { error in
            XCTAssertEqual(error as? AegisError, .proofVerificationFailed)
        }
    }

    func testMalformedEvaluationsNeverCrash() throws {
        let v = try vectors()
        let client = try VOPRFClient(publicKey: Data(hex: v.publicKey))
        let (_, state) = try client.blind(input: Data([1, 2, 3]))
        for junk in [Data(), Data([0, 2]), Data(repeating: 0xff, count: 99), Data(hex: "0002" + String(repeating: "00", count: 97))] {
            XCTAssertThrowsError(try client.finalize(state: state, evaluation: junk))
        }
        XCTAssertThrowsError(try VOPRFClient(publicKey: Data(repeating: 0xff, count: 32)))
    }

    func testExpandMessageXMDMatchesRFC9380Vector() {
        // RFC 9380 K.3 (expand_message_xmd, SHA-512), msg = "", len_in_bytes = 0x20.
        let dst = Array("QUUX-V01-CS02-with-expander-SHA512-256".utf8)
        XCTAssertEqual(Data(expandMessageXMD([], dst: dst, length: 0x20)).hex, "6b9a7312411d92f921c6f68ca0b6380730a1a4d982c507211a90964c394179ba")
    }
}

extension Data {
    init(hex: String) {
        var bytes = [UInt8]()
        var i = hex.startIndex
        while i < hex.endIndex {
            let j = hex.index(i, offsetBy: 2)
            bytes.append(UInt8(hex[i..<j], radix: 16)!)
            i = j
        }
        self.init(bytes)
    }
    var hex: String { map { String(format: "%02x", $0) }.joined() }
}
